// Denylist check for sensitive endpoints (sessions revoked by IdP events or admin action)
public sealed class RevokedSessionHandler(IDistributedCache cache) : AuthorizationHandler<NotRevokedRequirement>
{
    protected override async Task HandleRequirementAsync(AuthorizationHandlerContext ctx, NotRevokedRequirement r)
    {
        var sid = ctx.User.FindFirst("sid")?.Value;
        var jti = ctx.User.FindFirst("jti")?.Value;
        if (sid is null) return;
        var revoked = await cache.GetStringAsync($"revoked:sid:{sid}") is not null
                   || (jti is not null && await cache.GetStringAsync($"revoked:jti:{jti}") is not null);
        if (!revoked) ctx.Succeed(r);
    }
}

