// private_key_jwt client assertion signed with a key held in Key Vault (key never exported)
public async Task<string> CreateClientAssertionAsync(CryptographyClient signer, string clientId, string tokenEndpoint, CancellationToken ct)
{
    var now = DateTimeOffset.UtcNow;
    var header = Base64Url.EncodeToString(JsonSerializer.SerializeToUtf8Bytes(new { alg = "PS256", typ = "JWT", kid = signer.KeyId }));
    var payload = Base64Url.EncodeToString(JsonSerializer.SerializeToUtf8Bytes(new
    {
        iss = clientId, sub = clientId, aud = tokenEndpoint,
        jti = Guid.NewGuid().ToString("N"), iat = now.ToUnixTimeSeconds(), exp = now.AddMinutes(2).ToUnixTimeSeconds()
    }));
    var digest = SHA256.HashData(Encoding.ASCII.GetBytes($"{header}.{payload}"));
    var sig = await signer.SignAsync(SignatureAlgorithm.PS256, digest, ct);
    return $"{header}.{payload}.{Base64Url.EncodeToString(sig.Signature)}";
}
// Token request: client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer&client_assertion=...
