// Callback handling with explicit checks (frameworks do this; shown for clarity)
app.MapGet("/callback", async (HttpContext ctx, IAuthSessionStore store, ITokenClient tokens) =>
{
    var q = ctx.Request.Query;
    var pending = await store.TakeAsync(ctx);                                    // one-time: state, verifier, nonce, expected issuer
    if (pending is null || q["state"] != pending.State) return Results.BadRequest("invalid state");   // login CSRF
    if (q["iss"] != pending.ExpectedIssuer) return Results.BadRequest("issuer mismatch");             // RFC 9207 mix-up defence

    var t = await tokens.ExchangeAsync(q["code"]!, pending.CodeVerifier, redirectUri: "https://portal.bank.example/callback");
    var id = await tokens.ValidateIdTokenAsync(t.IdToken, expectedAudience: "portal", expectedNonce: pending.Nonce);   // nonce check
    await ctx.SignInAsync("cookies", id.Principal);
    ctx.Response.Headers["Referrer-Policy"] = "no-referrer";
    return Results.Redirect("/");                                                 // local redirect only
});
