app.MapPost("/bff/backchannel-logout", async (HttpRequest req, ILogoutTokenValidator validator, ISessionStore sessions) =>
{
    var form = await req.ReadFormAsync();
    var token = form["logout_token"].ToString();
    var claims = await validator.ValidateAsync(token);   // signature, iss, aud = this client, iat, jti unused, events contains backchannel-logout, no nonce
    if (claims is null) return Results.BadRequest();

    var sid = claims.FindFirst("sid")?.Value;
    var sub = claims.FindFirst("sub")?.Value;
    if (sid is not null) await sessions.DeleteBySidAsync(sid);
    else if (sub is not null) await sessions.DeleteBySubjectAsync(sub);
    return Results.Ok();
}).AllowAnonymous().DisableAntiforgery();
