~~~csharp
public async Task<bool> ValidateDPoPAsync(HttpContext ctx, ClaimsPrincipal tokenPrincipal, string accessToken, IReplayCache replay)
{
    var proof = ctx.Request.Headers["DPoP"].ToString();
    var jwt = new JsonWebToken(proof);
    if (jwt.Typ != "dpop+jwt" || !jwt.TryGetHeaderValue<JsonElement>("jwk", out var jwkJson)) return false;

    var jwk = new JsonWebKey(jwkJson.GetRawText());
    var result = await new JsonWebTokenHandler().ValidateTokenAsync(proof, new TokenValidationParameters
    {
        IssuerSigningKey = jwk, ValidateIssuer = false, ValidateAudience = false, ValidateLifetime = false,
        ValidAlgorithms = [SecurityAlgorithms.EcdsaSha256]
    });
    if (!result.IsValid) return false;

    var htm = jwt.GetClaim("htm").Value; var htu = jwt.GetClaim("htu").Value; var ath = jwt.GetClaim("ath").Value;
    var iat = DateTimeOffset.FromUnixTimeSeconds(long.Parse(jwt.GetClaim("iat").Value));
    var expectedUrl = $"{ctx.Request.Scheme}://{ctx.Request.Host}{ctx.Request.Path}";
    if (htm != ctx.Request.Method || htu != expectedUrl || Math.Abs((DateTimeOffset.UtcNow - iat).TotalSeconds) > 60) return false;
    if (ath != Base64Url.EncodeToString(SHA256.HashData(Encoding.ASCII.GetBytes(accessToken)))) return false;
    if (!await replay.TryAddAsync(jwt.Id, TimeSpan.FromMinutes(2))) return false;            // jti reuse

    var thumbprint = Base64Url.EncodeToString(jwk.ComputeJwkThumbprint());
    return tokenPrincipal.FindFirst("cnf")?.Value.Contains(thumbprint) == true;               // token bound to this key
}
