// Broker: map upstream claims explicitly; issuer-qualified subjects; never pass through privilege claims
public sealed class UpstreamClaimsMapper
{
    public ClaimsPrincipal Map(string upstreamIssuer, ClaimsPrincipal upstream, PartnerConfig partner)
    {
        var upstreamSub = upstream.FindFirst("sub")?.Value ?? upstream.FindFirst(ClaimTypes.NameIdentifier)!.Value;
        var id = new ClaimsIdentity("broker");
        id.AddClaim(new Claim("sub", ExternalSubject.Of(upstreamIssuer, upstreamSub)));     // collision-free
        id.AddClaim(new Claim("idp", partner.Name));
        id.AddClaim(new Claim("tenant", partner.TenantId));
        if (upstream.FindFirst("email") is { } email && partner.EmailIsVerifiedUpstream) id.AddClaim(new Claim("email", email.Value));
        var amr = upstream.FindAll("amr").Select(a => a.Value).ToHashSet();
        if (!amr.Overlaps(partner.AcceptedMfaMethods)) id.AddClaim(new Claim("requires_step_up", "true"));    // enforce MFA at broker
        // Roles come from our entitlement store for this tenant, never from upstream claims
        return new ClaimsPrincipal(id);
    }
}
