    var allowedRedirects = ((JsonElement)ssa.Claims["software_redirect_uris"]).EnumerateArray().Select(x => x.GetString()).ToHashSet();
    if (req.RedirectUris.Any(u => !allowedRedirects.Contains(u))) return Results.BadRequest(new { error = "invalid_redirect_uri" });
    if (req.TokenEndpointAuthMethod is not ("private_key_jwt" or "tls_client_auth")) return Results.BadRequest(new { error = "invalid_client_metadata" });
    if (!CertificateMatchesOrganisation(cert, (string)ssa.Claims["org_id"])) return Results.Unauthorized();

    var client = await clients.CreateAsync(req, scopes: ScopesFor(roles), orgId: (string)ssa.Claims["org_id"], ct);
