// Signing via HSM-backed key: AS never holds private key material
public sealed class HsmTokenSigner(CryptographyClient hsm, string kid) : ITokenSigner
{
    public string Algorithm => "ES256";
    public string KeyId => kid;

    public async Task<string> SignAsync(string header, string payload, CancellationToken ct)
    {
        var signingInput = Encoding.ASCII.GetBytes($"{header}.{payload}");
        var digest = SHA256.HashData(signingInput);
        var result = await hsm.SignAsync(SignatureAlgorithm.ES256, digest, ct);        // performed inside the HSM
        return $"{header}.{payload}.{Base64Url.EncodeToString(result.Signature)}";
    }
}
// Rotation job: create next key version in Managed HSM, publish its public JWK, switch after cache period, retire old after max lifetime
