// Kill switch: revoke all grants for a client and block new issuance
public async Task SuspendClientAsync(string clientId, string reason, CancellationToken ct)
{
    await clients.SetEnabledAsync(clientId, false, ct);                               // no new tokens
    var revoked = await grants.RevokeAllForClientAsync(clientId, ct);                 // refresh tokens and consents
    await consents.MarkSuspendedAsync(clientId, reason, ct);
    await denylist.AddClientAsync(clientId, TimeSpan.FromDays(30), ct);               // APIs reject outstanding access tokens for this client
    await audit.RecordAsync(new("client.suspended", clientId, reason, revoked), ct);
    await notifier.NotifyPartnerAsync(clientId, reason, ct);
}
