// Dynamic linking: the challenge signed by the customer's device key includes amount and payee
public static byte[] BuildScaChallenge(PaymentConsent c, string serverNonce) =>
    SHA256.HashData(Encoding.UTF8.GetBytes(string.Join('|',
        "payment", c.ConsentId, c.Amount.ToString("F2", CultureInfo.InvariantCulture), c.Currency, c.CreditorName, c.CreditorAccount, serverNonce)));

public async Task<ScaResult> VerifyAsync(PaymentConsent c, DeviceSignature sig, CancellationToken ct)
{
    var device = await devices.GetAsync(sig.DeviceId, ct);
    var challenge = BuildScaChallenge(c, sig.ServerNonce);
    var possession = device.PublicKey.VerifyHash(challenge, sig.Signature, DSASignatureFormat.Rfc3279DerSequence);   // possession
    var inherence = sig.UserVerification == "biometric";                                                           // inherence, enforced by key access control
    return possession && inherence
        ? ScaResult.Success(acr: "urn:bank:sca:possession+inherence", linkedTo: c.ConsentId)
        : ScaResult.Failed();
}
